SELECT 'core-2026-09-v4','past-modals','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"past-modals","title":"Past deductions, criticism and unnecessary actions","level":"B2","order":41,"summary":"Use modal perfect forms to look back at possibilities, missed opportunities and actions that were unnecessary.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Deductions about the past","Criticism and regret","Past possibility and opportunity","No need versus an unnecessary completed action"],"rules":[{"title":"Deductions about the past","explanation":"Use **modal + have + past participle** to evaluate an earlier event. Must have suggests a strong positive conclusion; can’t have suggests impossibility; might have leaves it uncertain. Have remains base form after every modal and every subject.","pattern":"She **must have left**. / They **might have missed** it.","commonMistakes":["Must had and must has are not standard modal-perfect forms."],"examples":["Make a past deduction: “She must **have prepared** the visitor guide before we arrived.”","Make a past deduction: “She must **have restored** the old portrait before we arrived.”"],"skill":"form"},{"title":"Criticism and regret","explanation":"Should have + past participle can describe a desirable action that did not happen, or an expectation about a completed event. Context decides which. Should not have often criticises an action that did happen.","pattern":"You **should have called**; we were worried.","commonMistakes":["Should have is not always blame: the parcel should have arrived by now can express an expectation."],"examples":["The task was not done, but doing it was advisable: “You **should** have prepared the visitor guide.”","The task was not done, but doing it was advisable: “You **should** have restored the old portrait.”"],"skill":"meaning"},{"title":"Past possibility and opportunity","explanation":"Could have may refer to a past possibility or an unrealised opportunity. Might have can express uncertainty about whether something happened. Read the context carefully before deciding whether the sentence states an actual event.","pattern":"We **could have stayed**, but we chose to leave.","commonMistakes":["Could have stayed does not by itself say that the person stayed."],"examples":["You did the task, but it was unnecessary: “You **need not** have prepared the visitor guide.”","You did the task, but it was unnecessary: “You **need not** have restored the old portrait.”"],"skill":"contrast"},{"title":"No need versus an unnecessary completed action","explanation":"Needn’t have + participle usually says an action happened but was unnecessary. Didn’t need to says there was no necessity and does not, by itself, settle whether the action happened. This meaning difference matters when offering reassurance.","pattern":"You **needn’t have waited**; I had a key.","commonMistakes":["Didn’t need to wait does not automatically mean that the person waited."],"examples":["Infer an ongoing past activity: “At that time, they might have **been preparing** the visitor guide.”","Infer an ongoing past activity: “At that time, they might have **been restoring** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Use modal perfect forms to look back at possibilities, missed opportunities and actions that were unnecessary.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Deductions about the past","explanation":"Use **modal + have + past participle** to evaluate an earlier event. Must have suggests a strong positive conclusion; can’t have suggests impossibility; might have leaves it uncertain. Have remains base form after every modal and every subject.","pattern":"She **must have left**. / They **might have missed** it.","commonMistakes":["Must had and must has are not standard modal-perfect forms."],"examples":["Make a past deduction: “She must **have prepared** the visitor guide before we arrived.”","Make a past deduction: “She must **have restored** the old portrait before we arrived.”"],"skill":"form","id":"past-modals-foundation-1","domain":"verbs","referenceIds":["bc-past-deduction"],"readingVersion":"core-2026-09-v3"},{"title":"Criticism and regret","explanation":"Should have + past participle can describe a desirable action that did not happen, or an expectation about a completed event. Context decides which. Should not have often criticises an action that did happen.","pattern":"You **should have called**; we were worried.","commonMistakes":["Should have is not always blame: the parcel should have arrived by now can express an expectation."],"examples":["The task was not done, but doing it was advisable: “You **should** have prepared the visitor guide.”","The task was not done, but doing it was advisable: “You **should** have restored the old portrait.”"],"skill":"meaning","id":"past-modals-foundation-2","domain":"verbs","referenceIds":["bc-past-deduction"],"readingVersion":"core-2026-09-v3"},{"title":"Past possibility and opportunity","explanation":"Could have may refer to a past possibility or an unrealised opportunity. Might have can express uncertainty about whether something happened. Read the context carefully before deciding whether the sentence states an actual event.","pattern":"We **could have stayed**, but we chose to leave.","commonMistakes":["Could have stayed does not by itself say that the person stayed."],"examples":["You did the task, but it was unnecessary: “You **need not** have prepared the visitor guide.”","You did the task, but it was unnecessary: “You **need not** have restored the old portrait.”"],"skill":"contrast","id":"past-modals-foundation-3","domain":"verbs","referenceIds":["bc-past-deduction"],"readingVersion":"core-2026-09-v3"},{"title":"No need versus an unnecessary completed action","explanation":"Needn’t have + participle usually says an action happened but was unnecessary. Didn’t need to says there was no necessity and does not, by itself, settle whether the action happened. This meaning difference matters when offering reassurance.","pattern":"You **needn’t have waited**; I had a key.","commonMistakes":["Didn’t need to wait does not automatically mean that the person waited."],"examples":["Infer an ongoing past activity: “At that time, they might have **been preparing** the visitor guide.”","Infer an ongoing past activity: “At that time, they might have **been restoring** the old portrait.”"],"skill":"application","id":"past-modals-foundation-4","domain":"verbs","referenceIds":["bc-past-deduction"],"readingVersion":"core-2026-09-v3"},{"domain":"verbs","id":"could-have-didnt-need","title":"Could have, might have and didn’t need to","explanation":"Modal + have + participle can express a judgement about the past, an unrealised opportunity or criticism. Could have does not always mean the event failed to happen; it can mean that it possibly happened. Needn’t have normally presents an action as done but unnecessary. Didn’t need to states absence of necessity and needs context to establish whether it happened.","pattern":"You **needn’t have bought** it.","examples":["She **could have missed** the train; I’m not sure.","We **didn’t need to book**, but we booked anyway."],"commonMistakes":["Do not assume every could have sentence is counterfactual. Contrast We could have won, but we lost with That noise could have been the wind."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["She **must have left**. / They **might have missed** it.","You **should have called**; we were worried.","We **could have stayed**, but we chose to leave.","You **needn’t have waited**; I had a key."],"readingVersion":"core-2026-09-v4"},"stage":"4 · Connecting meanings","prerequisites":["modal-deduction"],"readingReferenceIds":["bc-past-deduction","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='past-modals'
